using namespace std;

int main(){
    int n;
    if(scanf("%d",&n)!=1) return 0;
    vector<long long> x(n), y(n);
    for(int i=0;i<n;i++){
        long long a,b; scanf("%lld %lld",&a,&b);
        x[i]=a; y[i]=b;
    }
    const int O=n; // no origem como no extra

    // chave: d2 (30 bits) | a (11 bits) | b (11 bits)
    vector<unsigned long long> keys;
    keys.reserve((size_t)(n+1)*n/2);
    for(int i=0;i<n;i++){
        for(int j=i+1;j<=n;j++){
            long long xj,yj;
            if(j==n){xj=0;yj=0;}else{xj=x[j];yj=y[j];}
            long long dx=x[i]-xj, dy=y[i]-yj;
            long long d2=dx*dx+dy*dy;
            unsigned long long k=((unsigned long long)d2<<22)|((unsigned long long)i<<11)|(unsigned long long)j;
            keys.push_back(k);
        }
    }
    sort(keys.begin(),keys.end());

    vector<int> g(n+1,0), cand(n+1,0), stamp(n+1,-1);
    int grp=0;
    size_t i=0, m=keys.size();
    while(i<m){
        unsigned long long lvl=keys[i]>>22;
        size_t e=i;
        while(e<m && (keys[e]>>22)==lvl) e++;
        ++grp;
        // fase 1: acumula candidatos usando valores antigos de g
        for(size_t k=i;k<e;k++){
            int a=(int)((keys[k]>>11)&2047);
            int b=(int)(keys[k]&2047);
            if(stamp[a]!=grp){stamp[a]=grp;cand[a]=0;}
            if(stamp[b]!=grp){stamp[b]=grp;cand[b]=0;}
            if(b==O){
                int c=1+g[a];
                if(c>cand[O])cand[O]=c;
            }else{
                int c=1+g[b];
                if(c>cand[a])cand[a]=c;
                c=1+g[a];
                if(c>cand[b])cand[b]=c;
            }
        }
        // fase 2: aplica atualizações do nível
        for(size_t k=i;k<e;k++){
            int a=(int)((keys[k]>>11)&2047);
            int b=(int)(keys[k]&2047);
            if(stamp[a]==grp && cand[a]>g[a]) g[a]=cand[a];
            if(stamp[b]==grp && cand[b]>g[b]) g[b]=cand[b];
        }
        i=e;
    }
    printf("%d\n",g[O]);
    return 0;
}
